#include "grammar_lexer.h"

#include <stddef.h>

static bool is_identifier_start(unsigned char character)
{
    return (character >= (unsigned char)'A' &&
            character <= (unsigned char)'Z') ||
           (character >= (unsigned char)'a' &&
            character <= (unsigned char)'z') ||
           character == (unsigned char)'_';
}

static bool is_identifier_part(unsigned char character)
{
    return is_identifier_start(character) ||
           (character >= (unsigned char)'0' &&
            character <= (unsigned char)'9');
}

static bool is_ignored_space(unsigned char character)
{
    return character == (unsigned char)' ' ||
           character == (unsigned char)'\t' ||
           character == (unsigned char)'\v' ||
           character == (unsigned char)'\f' ||
           character == (unsigned char)'\r' ||
           character == (unsigned char)'\n';
}

static unsigned char current_character(const PbnfcGrammarLexer *lexer)
{
    return (unsigned char)lexer->source[lexer->offset];
}

static void advance_one(PbnfcGrammarLexer *lexer)
{
    unsigned char character = current_character(lexer);

    ++lexer->offset;
    if (character == (unsigned char)'\n') {
        ++lexer->line;
        lexer->column = 1U;
    } else {
        ++lexer->column;
    }
}

static void skip_ignored(PbnfcGrammarLexer *lexer)
{
    while (lexer->offset < lexer->length) {
        unsigned char character = current_character(lexer);

        if (is_ignored_space(character)) {
            advance_one(lexer);
        } else if (character == (unsigned char)'#') {
            while (lexer->offset < lexer->length &&
                   current_character(lexer) != (unsigned char)'\n') {
                advance_one(lexer);
            }
        } else {
            break;
        }
    }
}

static bool has_text(const PbnfcGrammarLexer *lexer,
                     size_t offset,
                     const char *text,
                     size_t length)
{
    size_t index;

    if (offset > lexer->length || length > lexer->length - offset) {
        return false;
    }
    for (index = 0U; index < length; ++index) {
        if (lexer->source[offset + index] != text[index]) {
            return false;
        }
    }
    return true;
}

static bool emit_error(PbnfcGrammarLexer *lexer,
                       const PbnfcLocation *location,
                       const char *detail)
{
    lexer->failed = true;
    if (lexer->diagnostics != NULL) {
        (void)pbnfc_diagnostic_emit(lexer->diagnostics, detail, location);
    }
    return false;
}

static void set_token(PbnfcGrammarToken *token,
                      PbnfcGrammarTokenKind kind,
                      PbnfcLocation location,
                      const char *text,
                      size_t length)
{
    token->kind = kind;
    token->location = location;
    token->text = text;
    token->length = length;
}

static bool read_directive(PbnfcGrammarLexer *lexer,
                           PbnfcGrammarToken *token,
                           PbnfcLocation location)
{
    size_t start = lexer->offset;
    size_t length;
    PbnfcGrammarTokenKind kind;

    if (has_text(lexer, start, "%start", 6U)) {
        length = 6U;
        kind = PBNFC_GRAMMAR_TOKEN_START_DIRECTIVE;
    } else if (has_text(lexer, start, "%token", 6U)) {
        length = 6U;
        kind = PBNFC_GRAMMAR_TOKEN_TOKEN_DIRECTIVE;
    } else {
        return emit_error(lexer, &location, "unknown grammar directive");
    }

    if (start + length < lexer->length &&
        is_identifier_part((unsigned char)lexer->source[start + length])) {
        return emit_error(lexer, &location, "malformed grammar directive");
    }

    while (length > 0U) {
        advance_one(lexer);
        --length;
    }
    set_token(token,
              kind,
              location,
              lexer->source + start,
              lexer->offset - start);
    return true;
}

static bool read_identifier(PbnfcGrammarLexer *lexer,
                            PbnfcGrammarToken *token,
                            PbnfcLocation location)
{
    size_t start = lexer->offset;

    while (lexer->offset < lexer->length &&
           is_identifier_part(current_character(lexer))) {
        advance_one(lexer);
    }
    set_token(token,
              PBNFC_GRAMMAR_TOKEN_IDENTIFIER,
              location,
              lexer->source + start,
              lexer->offset - start);
    return true;
}

static bool read_terminal(PbnfcGrammarLexer *lexer,
                          PbnfcGrammarToken *token,
                          PbnfcLocation location)
{
    size_t start = lexer->offset;

    /* Keep the complete source lexeme, including quotes and escape pairs. */
    advance_one(lexer);
    while (lexer->offset < lexer->length) {
        unsigned char character = current_character(lexer);

        if (character == (unsigned char)'\'') {
            advance_one(lexer);
            set_token(token,
                      PBNFC_GRAMMAR_TOKEN_TERMINAL,
                      location,
                      lexer->source + start,
                      lexer->offset - start);
            return true;
        }
        if (character == (unsigned char)'\n' ||
            character == (unsigned char)'\r') {
            return emit_error(lexer, &location, "unterminated grammar terminal");
        }
        if (character == (unsigned char)'\\') {
            advance_one(lexer);
            if (lexer->offset == lexer->length ||
                (current_character(lexer) != (unsigned char)'\'' &&
                 current_character(lexer) != (unsigned char)'\\')) {
                return emit_error(lexer, &location, "invalid grammar terminal escape");
            }
        }
        advance_one(lexer);
    }

    return emit_error(lexer, &location, "unterminated grammar terminal");
}

static bool read_reference(PbnfcGrammarLexer *lexer,
                           PbnfcGrammarToken *token,
                           PbnfcLocation location)
{
    size_t start = lexer->offset;

    advance_one(lexer);
    if (lexer->offset == lexer->length ||
        !is_identifier_start(current_character(lexer))) {
        return emit_error(lexer, &location, "malformed grammar token reference");
    }
    while (lexer->offset < lexer->length &&
           is_identifier_part(current_character(lexer))) {
        advance_one(lexer);
    }
    set_token(token,
              PBNFC_GRAMMAR_TOKEN_REFERENCE,
              location,
              lexer->source + start,
              lexer->offset - start);
    return true;
}

void pbnfc_grammar_lexer_init(PbnfcGrammarLexer *lexer,
                              const char *source,
                              size_t length,
                              const PbnfcDiagnosticContext *diagnostics)
{
    if (lexer == NULL) {
        return;
    }
    lexer->source = source;
    lexer->length = length;
    lexer->offset = 0U;
    lexer->line = 1U;
    lexer->column = 1U;
    lexer->diagnostics = diagnostics;
    lexer->failed = source == NULL && length != 0U;
}

bool pbnfc_grammar_lexer_next(PbnfcGrammarLexer *lexer,
                               PbnfcGrammarToken *token)
{
    PbnfcLocation location;
    size_t start;

    if (lexer == NULL || token == NULL || lexer->failed) {
        return false;
    }
    if (lexer->source == NULL && lexer->length != 0U) {
        return emit_error(lexer, NULL, "grammar source is unavailable");
    }

    skip_ignored(lexer);
    location.byte_offset = lexer->offset;
    location.line = lexer->line;
    location.column = lexer->column;
    start = lexer->offset;

    if (lexer->offset == lexer->length) {
        set_token(token,
                  PBNFC_GRAMMAR_TOKEN_EOF,
                  location,
                  lexer->source == NULL ? NULL : lexer->source + start,
                  0U);
        return true;
    }

    switch (current_character(lexer)) {
    case (unsigned char)'%':
        return read_directive(lexer, token, location);
    case (unsigned char)':':
        if (!has_text(lexer, start, "::=", 3U)) {
            return emit_error(lexer, &location, "expected ::= punctuation");
        }
        advance_one(lexer);
        advance_one(lexer);
        advance_one(lexer);
        set_token(token,
                  PBNFC_GRAMMAR_TOKEN_ASSIGN,
                  location,
                  lexer->source + start,
                  3U);
        return true;
    case (unsigned char)'|':
        advance_one(lexer);
        set_token(token,
                  PBNFC_GRAMMAR_TOKEN_PIPE,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    case (unsigned char)';':
        advance_one(lexer);
        set_token(token,
                  PBNFC_GRAMMAR_TOKEN_SEMICOLON,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    case (unsigned char)'\'':
        return read_terminal(lexer, token, location);
    case (unsigned char)'$':
        return read_reference(lexer, token, location);
    default:
        if (is_identifier_start(current_character(lexer))) {
            return read_identifier(lexer, token, location);
        }
        return emit_error(lexer, &location, "invalid character in grammar");
    }
}

bool pbnfc_grammar_lexer_failed(const PbnfcGrammarLexer *lexer)
{
    return lexer == NULL || lexer->failed;
}

const char *pbnfc_grammar_token_kind_name(PbnfcGrammarTokenKind kind)
{
    switch (kind) {
    case PBNFC_GRAMMAR_TOKEN_EOF:
        return "eof";
    case PBNFC_GRAMMAR_TOKEN_START_DIRECTIVE:
        return "%start";
    case PBNFC_GRAMMAR_TOKEN_TOKEN_DIRECTIVE:
        return "%token";
    case PBNFC_GRAMMAR_TOKEN_IDENTIFIER:
        return "identifier";
    case PBNFC_GRAMMAR_TOKEN_TERMINAL:
        return "terminal";
    case PBNFC_GRAMMAR_TOKEN_REFERENCE:
        return "token-reference";
    case PBNFC_GRAMMAR_TOKEN_ASSIGN:
        return "::=";
    case PBNFC_GRAMMAR_TOKEN_PIPE:
        return "|";
    case PBNFC_GRAMMAR_TOKEN_SEMICOLON:
        return ";";
    }
    return "unknown";
}

1-# Project: `pbnfc`, an eight-thread BNF compiler and markup recognizer
2-
3-Implement a self-contained ISO C11 command-line program that compiles a BNF
4:grammar and recognizes hierarchical HTML-like documents. The recognizer must
5-perform its parsing work through a persistent pool of exactly eight POSIX worker
6-threads and deterministically combine their partial results. External parser
7-generators and non-standard libraries are forbidden; POSIX `pthread` is allowed.
8-
9-This is not a file-splitting exercise. All eight workers cooperate on the chart
10-for one document. A coordinator distributes chart items in parallel rounds,
11-workers produce thread-local candidates, and the coordinator merges and
12:deduplicates those candidates in a stable order before the next round.
13-
14-## Required interface
15-
16-`make clean all` must build `bin/pbnfc` with strict warnings and pthread support.
17-
18-```text
19:bin/pbnfc --grammar PATH --input PATH [--start NAME] [--stats]
20-```
21-
22-On recognition success, exit 0 and print:
23-
24-```text
25-ACCEPT tokens=N
26-```
27-
--
30-```text
31-workers=8 active_workers=8 rounds=N tasks=N,N,N,N,N,N,N,N
32-```
33-
34-Every task count must be positive for the supplied stress document. `rounds`
35-must be positive. Without `--stats`, output must be deterministic and contain
36-no timing or scheduling-dependent values.
37-
38:For a syntactically valid grammar with rejected markup, exit 1 and print one
39-line beginning `REJECT ` with decimal byte `offset=`, `line=`, and `column=`
40-fields plus a nonempty `expected=` field. For command-line, markup-lexing,
41:grammar-lexing, grammar-parsing, undefined-symbol, or left-recursion errors,
42:exit 2 and print one line beginning `GRAMMAR_ERROR ` with useful detail.
43-
44-## Grammar language
45-
46-Whitespace is insignificant and `#` begins a comment through end of line. The
47:first directive is `%start NAME`. Zero or more token-kind declarations follow:
48-
49-```text
50:%token IDENT
51:%token STRING
52:%token TEXT
53-```
54-
55-Productions use `::=`, `|`, and `;`:
56-
57-```text
58:Name ::= symbol symbol | another-alternative | ;
59-```
60-
61-An empty alternative denotes epsilon. A single-quoted terminal matches an exact
62:markup token lexeme. Support `\\'` and `\\\\` escapes inside grammar terminals.
63-`$IDENT`, `$STRING`, and `$TEXT` match the declared markup token kind regardless
64-of lexeme. Bare identifiers are nonterminal references. Each rule name is
65-defined once and every nonterminal and `$TOKEN` reference must be defined.
66-
67-Detect direct and indirect left recursion before recognition. Right recursion,
68-epsilon, nested expansion, and ambiguous alternatives must terminate safely.
69-The engine must consume the entire markup token stream to accept. Do not
70-hard-code the acceptance examples or tag hierarchy in C; they come from the
71:compiled grammar.
72-
73-## Built-in markup lexer
74-
75-Tokenize compact markup without requiring whitespace between punctuation:
76-
77-- Inside `<...>`, recognize `<`, `>`, `/`, and `=` as exact literal lexemes.
78-- Recognize identifiers using `[A-Za-z_:][A-Za-z0-9_.:-]*`; their kind is
79-  `IDENT`, while exact terminals such as `'a'` may also match their lexeme.
80-- Recognize both single- and double-quoted attribute values as kind `STRING`,
81-  with backslash escapes for a quote and backslash.
82-- Outside tags, each nonempty maximal text run is one `TEXT` token. Preserve its
83-  byte location while ignoring runs that contain only ASCII whitespace.
84-- Reject unterminated tags, quoted values, and invalid bytes with accurate
85-  byte, line, and column diagnostics.
86-
87:The required grammar must be able to recognize compact nested markup such as:
88-
89-```html
90-<a href='url'> link text </a>
91-<div id="root"><p>Hello <strong>world</strong></p><img src='x.png'/></div>
92-```
93-
94:Opening and closing tags must match because the grammar defines separate rules
95-for `a`, `div`, `span`, `p`, `section`, `ul`, `li`, `strong`, and `em`; `img`
96-is self-closing. Attributes may appear on every tag and use the recursive
97-attribute productions. Mismatched, unknown, or malformed tags must reject.
98-
99-## Required eight-thread parser architecture
100-
101-Use a safe general chart recognizer, such as Earley recognition. Create exactly
102-eight worker pthreads once per process and reuse them until parsing ends.
103-
104-For each chart position and fixed-point closure wave:
105-
106-1. The coordinator snapshots the current unprocessed item range and partitions
107-   it across all eight workers.
108-2. Workers perform prediction/completion work and write only to their own
109:   candidate vectors; shared grammar and chart snapshots are read-only.
110-3. A barrier or condition-variable generation protocol returns control to the
111-   coordinator.
112-4. The coordinator stable-sorts or otherwise deterministically orders all
113:   candidates, merges duplicates, appends new items, and repeats until closure.
114-5. Scanning work is likewise distributed through the pool, with next-position
115-   candidates combined deterministically.
116-
117-All workers must perform real chart work on the stress case. Protect lifecycle
118-state with mutexes/condition variables or barriers, handle allocation failures,
119-join all threads on every normal/error exit, and avoid data races. Do not create
120-a new set of threads for every token or chart item. The coordinator is not one
121-of the eight reported workers.
